    def __await__(self):
        return self.sync().__await__()

    def with_changeset(self, changes: Self, *, on_conflict: ChangesetMergeConflict | None = ChangesetMergeConflict.FAIL,) -> Self:
        """Add changes to an existing changeset

        By default the operation will fail in case of conflicts, for instance
        a file modified in both changesets. The behavior can be adjusted using
        onConflict argument

        Parameters
        ----------
        changes:
            Changes to merge into the actual changeset
        on_conflict:
            What to do on a merge conflict
        """
        if not (isinstance(changes, Changeset)):
            raise _type_error("Changeset.with_changeset", "changes", changes, "Changeset")
        if not (on_conflict is None or isinstance(on_conflict, ChangesetMergeConflict)):
            raise _type_error("Changeset.with_changeset", "on_conflict", on_conflict, "ChangesetMergeConflict | None")
        _args = [
            Arg("changes", changes),
            Arg("onConflict", on_conflict, ChangesetMergeConflict.FAIL),
        ]
        _ctx = self._select("withChangeset", _args)
        return Changeset(_ctx)

    def with_changesets(self, changes: list["Changeset"], *, on_conflict: ChangesetsMergeConflict | None = ChangesetsMergeConflict.FAIL,) -> Self:
        """Add changes from multiple changesets using git octopus merge strategy

        This is more efficient than chaining multiple withChangeset calls when
        merging many changesets.

        Only FAIL and FAIL_EARLY conflict strategies are supported (octopus
        merge cannot use -X ours/theirs).

        Parameters
        ----------
        changes:
            List of changesets to merge into the actual changeset
        on_conflict:
            What to do on a merge conflict
        """
        if not (isinstance(changes, list) and all(isinstance(_v0, Changeset) for _v0 in changes)):
            raise _type_error("Changeset.with_changesets", "changes", changes, "list[Changeset]")
        if not (on_conflict is None or isinstance(on_conflict, ChangesetsMergeConflict)):
            raise _type_error("Changeset.with_changesets", "on_conflict", on_conflict, "ChangesetsMergeConflict | None")
        _args = [
            Arg("changes", changes),
            Arg("onConflict", on_conflict, ChangesetsMergeConflict.FAIL),
        ]
        _ctx = self._select("withChangesets", _args)
        return Changeset(_ctx)

    def with_(self, cb: Callable[["Changeset"], "Changeset"]) -> "Changeset":
        """Call the provided callable with current Changeset.

        This is useful for reusability and readability by not breaking the calling chain.
        """
        return cb(self)



